#include <stdio.h>

/* retanguloDeHashtags le dois inteiros (linhas e colunas) e desenha um
   retangulo de #.
   O laco de fora ja esta pronto: ele conta as linhas e imprime a quebra.
   Falta o laco DE DENTRO, que escreve as marcas de uma linha. */
void retanguloDeHashtags(void) {
    int linhas = 0;
    int colunas = 0;
    scanf("%d %d", &linhas, &colunas);

    for (int linha = 1; linha <= linhas; linha++) {
        /* escreva aqui o laco de dentro: colunas vezes o caractere # */

        printf("\n");
    }
}

