#include <stdio.h>

/* teste do desafio retangulo-de-hashtags — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os nomes dos arquivos temporarios sao POR CENARIO: um cenario nunca le a
   entrada nem a captura do outro. Nunca ha fclose de stdin/stdout — so
   fflush — para o segundo freopen ficar legal (C11 7.21.4).
   Os dois desenhos tem tamanhos diferentes de proposito: um retangulo
   escrito a mao no codigo passaria num cenario e reprovaria no outro. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void retanguloDeHashtags(void);

SM_TEST(o_retangulo_3_por_4) {
    /* o que a pessoa digita: 3 linhas e 4 colunas */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "3 4\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    retanguloDeHashtags();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("linha 1 de 3x4", linha, "####\n",
              "a linha 1 do retangulo tem 4 marcas");
    fgets(linha, 80, f);
    checa_str("linha 2 de 3x4", linha, "####\n",
