    fgets(linha, 80, f);
    checa_str("linha 3 de 3x4", linha, "####\n",
              "a linha 3 do retangulo tem 4 marcas");

    /* a saida TERMINA na linha 3 — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
