#include <stdio.h>

void retanguloDeHashtags(void) {
    int linhas = 0;
    int colunas = 0;
    scanf("%d %d", &linhas, &colunas);

    for (int linha = 1; linha <= linhas; linha++) {
        for (int coluna = 1; coluna <= colunas; coluna++) {
            printf("#");
        }

        printf("\n");
    }
}
